const body = $json.body || $json;

return [{
  json: {
    name: body.name || 'Unknown Lead',
    email: body.email || '',
    company: body.company || '',
    stage: body.stage || 'New Lead',
    source: body.source || 'Webhook',
    notes: body.notes || '',
    lastActivity: new Date().toISOString(),
    nextTask: body.nextTask || 'Review and qualify lead'
  }
}];

const stage = ($json.stage || '').toLowerCase();
let crmAction = 'CREATE_GENERAL_FOLLOW_UP';
let priority = 'Medium';
let recommendedNextStep = 'Review the contact and decide the correct pipeline stage.';

if (stage.includes('new')) {
  crmAction = 'CREATE_LEAD_RECORD';
  priority = 'Medium';
  recommendedNextStep = 'Qualify the lead and send an initial follow-up.';
}

if (stage.includes('hot')) {
  crmAction = 'CREATE_DEAL_RECORD';
  priority = 'High';
  recommendedNextStep = 'Contact immediately and attempt to book a sales call.';
}

if (stage.includes('client')) {
  crmAction = 'CREATE_CLIENT_TASK';
  priority = 'High';
  recommendedNextStep = 'Create an onboarding or client success task.';
}

return [{
  json: {
    ...$json,
    crmAction,
    priority,
    recommendedNextStep
  }
}];

return [{
  json: {
    status: 'CRM_AUTOMATION_READY',
    processedAt: new Date().toISOString(),
    contact: {
      name: $json.name,
      email: $json.email,
      company: $json.company,
      source: $json.source
    },
    crm: {
      stage: $json.stage,
      action: $json.crmAction,
      priority: $json.priority,
      nextTask: $json.nextTask,
      recommendedNextStep: $json.recommendedNextStep,
      notes: $json.notes
    }
  }
}];
